const logs = ["Mars", "Moon", "Mars", "Venus", "Moon", "Mars"];

const planets = new Set(logs);
console.log(planets);
console.log("Different planets:", planets.size);

const visits = new Map();
for (const p of logs) {
  visits.set(p, (visits.get(p) || 0) + 1);
}
console.log(visits);
console.log("Mars visits:", visits.get("Mars"));

