challenge.solution:
const signals = ["beep", "whoosh", "beep", "click", "beep", "whoosh"];

function countWords(list) {
  const counts = new Map();
  // count every word
  for (const word of list) {
    counts.set(word, (counts.get(word) || 0) + 1);
  }
  return counts;
}

function mostCommon(list) {
  // the most common word
  let best = null;
  let bestCount = 0;
  for (const [word, count] of countWords(list)) {
    if (count > bestCount) {
      best = word;
      bestCount = count;
    }
  }
  return best;
}

console.log(countWords(signals));
console.log("Most common:", mostCommon(signals));

